-- 0069_retranslate_program_content.sql
-- Фаза 27: вычитка и полный перевод контента программ (EN / ES / HY)
-- + все 8 программ — годовые (48 недель).
--
-- 1. duration_weeks = 48 у всех 8 программ. Во всех восьми документах
--    тренера — 12 месяцев (48 недель), а в базе у трёх программ стояло
--    24/24/72 (ошибка разбора исходников).
-- 2. RU-чистка названий тренировок: убираем "День N · " и
--    "Неделя N, День N · " (тот же принцип, что с днями недели в 0068) —
--    порядок и так виден по неделе и номеру тренировки.
-- 3. Переводы: прежние EN/ES/HY (0030–0058) были сделаны словарной
--    заменой и местами оставляли русские слова ("Circuit ×4: 10
--    отжиманий…"). Здесь — полностью заново переведённые тексты:
--    2062 упражнений (в 0070–0071), 483 заметок к подходам,
--    276 названий тренировок, 163 подписей недель,
--    названия и описания программ (включая старую "Набор массы для
--    начинающих" из 0002, у которой переводов не было вовсе). Английские названия упражнений
--    (Hip Thrust, Mountain Climbers…) остаются как есть во всех языках —
--    так их и знают в залах.
--
-- Сопоставление — по точному русскому тексту (title / week_label / notes),
-- поэтому не зависит от порядка и id. Безопасно выполнять повторно.

-- 1. Длительность ---------------------------------------------------------
update public.workout_programs set duration_weeks = 48
where slug in ('pohudenie-zhenshchiny-doma', 'pohudenie-zhenshchiny-zal', 'nabor-massy-zhenshchiny-doma', 'nabor-massy-zhenshchiny-zal', 'pohudenie-muzhchiny-doma', 'pohudenie-muzhchiny-zal', 'nabor-massy-muzhchiny-doma', 'nabor-massy-muzhchiny-zal') and duration_weeks <> 48;

-- 2. RU-чистка названий тренировок ----------------------------------------
update public.workouts set title = 'PUSH (полная смена упражнений)' where title = 'Неделя 4, День 1 — PUSH · PUSH (полная смена упражнений)';
update public.workouts set title = 'PULL' where title = 'Неделя 4, День 2 — PULL · PULL';
update public.workouts set title = 'НОГИ + ATHLETIC' where title = 'Неделя 4, День 3 — НОГИ + ATHLETIC · НОГИ + ATHLETIC';

update public.workouts
set title = regexp_replace(title, '^(Неделя [0-9]+, )?День [0-9]+ · ', '')
where title ~ '^(Неделя [0-9]+, )?День [0-9]+ · ';

-- 3. Программы -----------------------------------------------------------
update public.workout_programs p
set title_en = v.title_en, title_es = v.title_es, title_hy = v.title_hy,
    description_en = v.description_en, description_es = v.description_es, description_hy = v.description_hy
from (values
  ('pohudenie-zhenshchiny-doma', 'Weight Loss · Women · Home', 'Pérdida de peso · Mujeres · Casa', 'Քաշի նվազեցում · Կանայք · Տանը', 'Weight loss for women (at home) — DonatelleX, one-year program. Equipment: Dumbbells, resistance bands of different strengths, mat, stable platform/step (if available)', 'Pérdida de peso para mujeres (en casa) — DonatelleX, programa anual. Equipo: Mancuernas, bandas elásticas de distinta resistencia, esterilla, plataforma/escalón estable (si es posible)', 'Քաշի նվազեցում կանանց համար (տանը) — DonatelleX, տարեկան ծրագիր. Սարքավորումներ: Հանտելներ, տարբեր կոշտության ռետինե ժապավեններ, գորգ, կայուն հարթակ/աստիճան (հնարավորության դեպքում)'),
  ('pohudenie-zhenshchiny-zal', 'Weight Loss · Women · Gym', 'Pérdida de peso · Mujeres · Gimnasio', 'Քաշի նվազեցում · Կանայք · Մարզասրահ', 'Weight loss for women (at the gym) — one-year program. Equipment: Treadmill, elliptical/ski erg, machines, dumbbells, cables, mat', 'Pérdida de peso para mujeres (en el gimnasio) — programa anual. Equipo: Cinta de correr, elíptica/esquí, máquinas, mancuernas, poleas, esterilla', 'Քաշի նվազեցում կանանց համար (մարզասրահում) — տարեկան ծրագիր. Սարքավորումներ: Վազքուղի, էլիպս/դահուկային տրենաժոր, տրենաժորներ, հանտելներ, տրոսներ, գորգ'),
  ('nabor-massy-zhenshchiny-doma', 'Muscle Gain · Women · Home', 'Ganancia muscular · Mujeres · Casa', 'Մկանային զանգված · Կանայք · Տանը', 'Muscle gain for women (at home) — one-year program. Equipment: Dumbbells, resistance bands of different strengths, mat, stable platform/step', 'Ganancia muscular para mujeres (en casa) — programa anual. Equipo: Mancuernas, bandas elásticas de distinta resistencia, esterilla, plataforma/escalón estable', 'Մկանային զանգվածի հավաքում կանանց համար (տանը) — տարեկան ծրագիր. Սարքավորումներ: Հանտելներ, տարբեր կոշտության ռետինե ժապավեններ, գորգ, կայուն հարթակ/աստիճան'),
  ('nabor-massy-zhenshchiny-zal', 'Muscle Gain · Women · Gym', 'Ganancia muscular · Mujeres · Gimnasio', 'Մկանային զանգված · Կանայք · Մարզասրահ', 'Muscle gain for women (at the gym) — one-year program «12 LEVELS». Equipment: Barbell, dumbbells, machines (Hip Thrust, Hack Squat, Leg Press, cables), resistance bands, kettlebells, TRX, medicine ball', 'Ganancia muscular para mujeres (en el gimnasio) — programa anual «12 LEVELS». Equipo: Barra, mancuernas, máquinas (Hip Thrust, Hack Squat, Leg Press, poleas), bandas elásticas, kettlebells, TRX, balón medicinal', 'Մկանային զանգվածի հավաքում կանանց համար (մարզասրահում) — տարեկան ծրագիր «12 LEVELS». Սարքավորումներ: Ձող, հանտելներ, տրենաժորներ (Hip Thrust, Hack Squat, Leg Press, բլոկներ), ռետինե ժապավեններ, գիրաներ, TRX, մեդբոլ'),
  ('pohudenie-muzhchiny-doma', 'Weight Loss · Men · Home', 'Pérdida de peso · Hombres · Casa', 'Քաշի նվազեցում · Տղամարդիկ · Տանը', 'Weight loss for men (at home) — one-year program. Equipment: Dumbbells, resistance bands, pull-up bar (if available), chair/bench, mat', 'Pérdida de peso para hombres (en casa) — programa anual. Equipo: Mancuernas, bandas elásticas, barra de dominadas (si es posible), silla/banco, esterilla', 'Քաշի նվազեցում տղամարդկանց համար (տանը) — տարեկան ծրագիր. Սարքավորումներ: Հանտելներ, ռետինե ժապավեններ, պտտաձող (հնարավորության դեպքում), աթոռ/նստարան, գորգ'),
  ('pohudenie-muzhchiny-zal', 'Weight Loss · Men · Gym', 'Pérdida de peso · Hombres · Gimnasio', 'Քաշի նվազեցում · Տղամարդիկ · Մարզասրահ', 'Weight loss for men (at the gym) — one-year program. Equipment: Barbell, dumbbells, machines, cables, Battle Rope, SkiErg/rowing machine, cardio area (treadmill/elliptical/stationary bike)', 'Pérdida de peso para hombres (en el gimnasio) — programa anual. Equipo: Barra, mancuernas, máquinas, poleas, Battle Rope, SkiErg/remo, zona de cardio (cinta/elíptica/bicicleta estática)', 'Քաշի նվազեցում տղամարդկանց համար (մարզասրահում) — տարեկան ծրագիր. Սարքավորումներ: Ձող, հանտելներ, տրենաժորներ, բլոկներ, Battle Rope, SkiErg/թիավարման տրենաժոր, կարդիո գոտի (վազքուղի/էլիպս/վելոտրենաժոր)'),
  ('nabor-massy-muzhchiny-doma', 'Muscle Gain · Men · Home', 'Ganancia muscular · Hombres · Casa', 'Մկանային զանգված · Տղամարդիկ · Տանը', 'Muscle gain for men (at home) — one-year program. Equipment: Dumbbells, resistance bands, pull-up bar (if available), chair/bench, mat', 'Ganancia muscular para hombres (en casa) — programa anual. Equipo: Mancuernas, bandas elásticas, barra de dominadas (si es posible), silla/banco, esterilla', 'Մկանային զանգվածի հավաքում տղամարդկանց համար (տանը) — տարեկան ծրագիր. Սարքավորումներ: Հանտելներ, ռետինե ժապավեններ, պտտաձող (հնարավորության դեպքում), աթոռ/նստարան, գորգ'),
  ('nabor-massy-muzhchiny-zal', 'Muscle Gain · Men · Gym', 'Ganancia muscular · Hombres · Gimnasio', 'Մկանային զանգված · Տղամարդիկ · Մարզասրահ', 'Muscle gain for men (at the gym) — one-year program. Equipment: Full gym setup: barbells, dumbbells, machines, pull-up bar, ropes, TRX, kettlebells', 'Ganancia muscular para hombres (en el gimnasio) — programa anual. Equipo: Gimnasio completo: barras, mancuernas, máquinas, barra de dominadas, cuerdas, TRX, kettlebells', 'Մկանային զանգվածի հավաքում տղամարդկանց համար (մարզասրահում) — տարեկան ծրագիր. Սարքավորումներ: Մարզասրահի ամբողջական հավաքածու: ձողեր, հանտելներ, տրենաժորներ, պտտաձող, պարաններ, TRX, գիրաներ'),
  ('nabor-massy-nachinayushchim', 'Muscle Gain for Beginners', 'Ganancia muscular para principiantes', 'Մկանային զանգված սկսնակների համար', 'A first program for men who want to start building muscle in the gym. 7-day cycle: 4 strength workouts for different muscle groups and 3 days of light cardio with abs. Beginner-friendly — no complex technique, focus on volume and proper form.', 'Un primer programa para hombres que quieren empezar a ganar masa muscular en el gimnasio. Ciclo de 7 días: 4 entrenamientos de fuerza para distintos grupos musculares y 3 días de cardio suave con abdomen. Apto para principiantes: sin técnica compleja, con el foco en el volumen y la buena ejecución.', 'Առաջին ծրագիր տղամարդկանց համար, ովքեր ցանկանում են սկսել մկանային զանգված հավաքել մարզասրահում։ 7-օրյա ցիկլ՝ 4 ուժային մարզում տարբեր մկանախմբերի համար և 3 օր թեթև կարդիո՝ մամլիչով։ Հարմար է սկսնակների համար՝ առանց բարդ տեխնիկայի, շեշտը ծավալի և ճիշտ կատարման վրա։')
